import{_ as l,l as s,o as e,c as o,v as t,p as n,x as i,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"跳表","description":"","frontmatter":{"title":"跳表","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/skip-list.md","filePath":"cs/skip-list.md","lastUpdated":1789023840000}'),c={name:"cs/skip-list.md"};function _(B,a,m,E,u,f){const r=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="跳表" tabindex="-1">跳表 <a class="header-anchor" href="#跳表" aria-label="Permalink to &quot;跳表&quot;">​</a></h1><div class="epigraph"><p>在有序链表上随机加几层快进指针，期望查找变成对数，而不必维护旋转不变式。</p><footer>—— 据 Pugh, Skip Lists: A Probabilistic Alternative to Balanced Trees, CACM 1990 整理</footer></div><p><a href="/cs/bloom-filter">上一课</a>的散列不保序。<a href="/cs/rbtree-intuition">红黑树直觉</a>保序但要颜色与旋转。<a href="/cs/linked-list-locality">链表与局部性代价</a>的有序链表查找是 \\(\\Theta(n)\\)。本课不重讲探测序列。缺口是：用随机化给链表加「快递层」，期望 \\(O(\\log n)\\) 查找/插入/删除，实现比红黑短。最坏仍可退化，合同写期望。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有序字典若坚持最坏对数，必须平衡树。若接受期望对数（与随机 BST、散列同类），可以让每个节点以 \\(1/2\\) 概率升高一层，高层是底层的稀疏捷径。缺口不是新的键比较，而是<strong>层高随机、搜索从最高层向右再向下</strong>。</p><p>Pugh 1990 把这套结构写成可实用的替代。本课不把并发跳表的 CAS 细节写进来。</p><p><span class="marginnote">期望高度 \\(O(\\log n)\\)，空间期望 \\(O(n)\\)。与 AVL 的确定对数不同，与散列的不保序也不同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>底层是有序链表。节点有 \\(h\\) 个前向指针，\\(h\\) 在插入时抛硬币决定。查找：从最高层头节点向右，下一步会超过目标则下一层。插入：先查找记下每层前驱，再抛硬币建节点、接线。删除：同样前驱改指针。</p>',9)),(e(),n(h,null,{default:i(()=>[p(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20L2%5B%22%E5%B1%82%202%20%E5%BF%AB%E8%BF%9B%22%5D%20--%3E%20L1%5B%22%E5%B1%82%201%22%5D%0A%20%20L1%20--%3E%20L0%5B%22%E5%B1%82%200%20%E6%9C%89%E5%BA%8F%E9%93%BE%E8%A1%A8%22%5D%0A%20%20L2%20--%3E%20SRCH%5B%22%E5%90%91%E5%8F%B3%E7%9B%B4%E8%87%B3%E5%B0%86%E8%B6%8A%E8%BF%87%EF%BC%8C%E5%86%8D%E5%90%91%E4%B8%8B%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/amortized-analysis">摊还分析</a>不同：这里是概率期望，不是最坏摊还。可以高概率说高度 \\(O(\\log n)\\)，仍不是 AVL 那种确定界。硬币概率取 \\(1/2\\) 只是常见默认；改成 \\(1/p\\) 只调层数期望，不改对数形态。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>中序就是底层链表遍历，范围查询自然。散列做不到这一点。旋转代码量为零，正确性主要在接线。局部性仍差：多层指针比数组跳得更散；B 树外存仍赢。内存里跳表常数可接受，且实现短。头节点必须具备最高层指针，否则无法从顶层起步。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把跳表写成「永远替代红黑」。实时最坏路径仍可能碰到未升高的长链，尽管概率小。也不引入确定性跳表。字符串前缀共享是另一结构：Trie。</p><p>后课默认：有序字典可以树或跳表。按字符前缀压缩路径，用 Trie。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跳表 = 有序链表 + 随机快进层，期望对数。</li><li>保序、实现短；最坏与局部性弱于平衡树和 B 树。</li><li>前缀键的共享路径是下一课 Trie。</li><li>合同写期望，不写 AVL 那种确定对数。</li><li>头节点必须具备最高层指针，查找才能从顶层起步。</li><li>出处：Pugh, <em>CACM</em>, 1990。</li></ul>',8))])}const b=l(c,[["render",_]]);export{T as __pageData,b as default};
